import Foundation
import ClavuneCore

/// Interface choice is deliberately independent of ClavuneCore.LanguageMode.
/// German source keys keep existing coordinator diagnostics/test oracles stable.
enum UILanguage: String, CaseIterable, Identifiable {
    case english = "en", german = "de"
    var id: String { rawValue }
    func text(_ source: String) -> String {
        guard self == .english else { return source }
        if let translated = Self.englishText[source] { return translated }
        if source.hasSuffix(" Bytes"), let separator = source.range(of: ": ") {
            let name = source[..<separator.lowerBound]
            let values = String(source[separator.upperBound...].dropLast(" Bytes".count)).components(separatedBy: " / ")
            if values.count == 2, let received = Int64(values[0]), let total = Int64(values[1]) {
                return "\(name): \(received) / \(total) bytes"
            }
        }
        for suffix in [" — Hash geprüft, Qualität noch ungemessen", " registriert (vorläufig)"] {
            if source.hasSuffix(suffix), let translated = Self.englishText[suffix] {
                return text(String(source.dropLast(suffix.count))) + translated
            }
        }
        return source // Device names, filenames and technical shortcut names are not translated.
    }
    /// Present the pinned catalogue's role identifiers as readable candidate labels.
    /// Unknown/test-only roles remain literal rather than gaining an invented status.
    func modelRole(_ role: String) -> String {
        switch role {
        case "comparison-candidate": return text("Vergleichskandidat")
        case "product-candidate": return text("Produktkandidat")
        case "reference-candidate": return text("Referenzkandidat")
        default: return role
        }
    }
    func downloadFailureMessage(for error: Error) -> String {
        if let error = error as? ModelDownloadFailure { return text(error.localizedDescription) }
        if let error = error as? ModelStore.RecoveryError { return text(error.localizedDescription) }
        if let error = error as? DictationError { return text(error.localizedDescription) }
        if error is URLError {
            return text("Der Modelldownload wurde unterbrochen. Prüfe die Verbindung und wähle den Download erneut; Teildaten werden nur bei passender Quellenprüfung fortgesetzt.")
        }
        return text("Der Modelldownload ist fehlgeschlagen. Bitte prüfe Verbindung und Speicherplatz und versuche es erneut.")
    }
